  const retire=()=>{attempt.cancel.abort();if(this.attempt===attempt){this.attempt=undefined;this.pendingBooklet.set('');}};
  scope.addEventListener('abort',retire,{once:true});owner.addEventListener('abort',retire,{once:true});
